import { BaseHandler } from "../../response/base.js";
import { getApiHandler, withApiHandler } from "./pages-api-handler.js";
import { ensurePreviewSourceSnapshotFresh, preparePreviewDocumentSourceSnapshot, } from "../source-snapshot-freshness.js";
import { PRIORITY_MEDIUM_API } from "../../../../utils/constants/index.js";
import { withSpan } from "../../../../observability/tracing/otlp-setup.js";
import { ensureProjectDiscovery } from "./project-discovery.js";
import { PageResolver } from "../../../../rendering/page-resolution/page-resolver.js";
import { createErrorResponseFromDefinition, PROJECT_EXECUTION_UNAVAILABLE, } from "../../../../errors/index.js";
import { requiresIsolatedProjectRuntime } from "../../../../security/project-locality.js";
import { isPreflightRequest } from "../../../../security/http/cors/preflight.js";
import { getApplicationPreflightHeaders } from "../../../../security/http/application-request.js";
import { DEFAULT_CORS_METHODS, handleCORSPreflight } from "../../../../security/index.js";
import { createHostApplicationInferenceAdmission } from "./application-inference-admission.js";
import { runWithApplicationInferenceAdmission } from "../../../../agent/runtime/application-inference-admission.js";
export class ApiHandlerWrapper extends BaseHandler {
    projectDir;
    adapter;
    initPromise = null;
    metadata = {
        name: "ApiHandlerWrapper",
        priority: PRIORITY_MEDIUM_API,
    };
    constructor(projectDir, adapter) {
        super();
        this.projectDir = projectDir;
        this.adapter = adapter;
    }
    async initialize() {
        this.initPromise ??= (async () => {
            await getApiHandler({
                projectDir: this.projectDir,
                adapter: this.adapter,
            });
        })();
        await this.initPromise;
    }
    async prepareFrameworkOwnedPreflight(req, ctx) {
        if (req.method.toUpperCase() !== "OPTIONS")
            return false;
        const isBrowserPreflight = isPreflightRequest(req);
        if (requiresIsolatedProjectRuntime(ctx)) {
            if (isBrowserPreflight)
                ctx.frameworkOwnedPreflight = true;
            return isBrowserPreflight;
        }
        const fsWrapper = ctx.adapter.fs;
        const isMultiProject = !!ctx.projectSlug &&
            typeof fsWrapper.isMultiProjectMode === "function" &&
            fsWrapper.isMultiProjectMode();
        const inspect = async () => {
            await preparePreviewDocumentSourceSnapshot(ctx);
            const result = await withApiHandler(ctx, (api) => api.prepareFrameworkOwnedPreflight(req, ctx), { sourceSnapshotReady: true });
            ctx.frameworkOwnedPreflight = result.frameworkOwned;
            if (result.response)
                ctx.frameworkPreflightResponse = result.response;
            return result.frameworkOwned;
        };
        if (!isMultiProject) {
            if (fsWrapper.isContextualMode?.() === true)
                return false;
            return await inspect();
        }
        return await fsWrapper.runWithContext(ctx.projectSlug, ctx.proxyToken ?? "", inspect, ctx.projectId, {
            productionMode: ctx.requestContext?.mode === "production",
            releaseId: ctx.releaseId,
            branch: ctx.requestContext?.mode === "production"
                ? null
                : ctx.requestContext?.branch ?? ctx.parsedDomain?.branch ?? null,
            environmentName: ctx.environmentName,
        });
    }
    async handle(req, ctx) {
        const { pathname } = new URL(req.url);
        this.logDebug("[API-Wrapper] Handling request", {
            pathname,
            projectDir: ctx.projectDir,
            projectSlug: ctx.projectSlug,
        }, ctx);
        const fsWrapper = ctx.adapter.fs;
        const isMultiProject = !!ctx.projectSlug &&
            typeof fsWrapper.isMultiProjectMode === "function" &&
            fsWrapper.isMultiProjectMode();
        const mustDenyProjectExecution = requiresIsolatedProjectRuntime(ctx);
        if (!isMultiProject) {
            // Request-global token and branch mutators cannot keep classification
            // and the later render on one context when requests overlap. Only an
            // atomic runWithContext adapter may serve contextual project source.
            if (fsWrapper.isContextualMode?.() === true) {
                return this.projectExecutionUnavailable(req, ctx, pathname, "Contextual project filesystem access requires atomic request-scoped execution");
            }
            return this.handleWithContext(req, ctx, pathname, mustDenyProjectExecution);
        }
        const isProduction = ctx.requestContext?.mode === "production";
        this.logDebug("[API-Wrapper] Using multi-project context", {
            projectSlug: ctx.projectSlug,
            projectId: ctx.projectId,
            hasProxyToken: !!ctx.proxyToken,
            productionMode: isProduction,
        }, ctx);
        return fsWrapper.runWithContext(ctx.projectSlug, ctx.proxyToken ?? "", 
        // Multi-project mode implies a shared runtime, but not that execution is
        // denied: a host-owned entrypoint can still have granted the capability.
        () => this.handleWithContext(req, ctx, pathname, mustDenyProjectExecution), ctx.projectId, {
            productionMode: isProduction,
            releaseId: ctx.releaseId,
            branch: isProduction ? null : ctx.requestContext?.branch ?? ctx.parsedDomain?.branch ??
                null,
            environmentName: ctx.environmentName,
        });
    }
    async handleWithContext(req, ctx, pathname, mustDenyProjectExecution) {
        return withSpan("api.handleWithContext", async () => {
            if (req.signal.aborted)
                throw req.signal.reason;
            if (mustDenyProjectExecution) {
                return await this.handleDeniedProjectExecution(req, ctx, pathname);
            }
            const preparedResponse = this.handlePreparedFrameworkPreflight(req, ctx);
            if (preparedResponse)
                return preparedResponse;
            const canResolveAsPage = this.canResolveAsPage(req, pathname);
            // A document path can change ownership between App Router page and
            // route.ts without changing the branch identity. Establish strict
            // freshness before classifying it, then let SSR reuse that snapshot.
            // This must stay outside the API-discovery catch: downstream document
            // handlers must never serve an older snapshot after freshness fails.
            await this.prepareApiSourceSnapshot(req, ctx, pathname, mustDenyProjectExecution, canResolveAsPage);
            try {
                return await this.handleDiscoveredApiRequest(req, ctx, pathname, canResolveAsPage);
            }
            catch (error) {
                if (req.signal.aborted)
                    throw error;
                this.logDebug("[API-Wrapper] API handler error - falling through to next handler", {
                    pathname,
                    error: this.getErrorMessage(error),
                    stack: error instanceof Error ? error.stack : undefined,
                }, ctx);
                return this.continue();
            }
        }, {
            "api.pathname": pathname,
            "api.method": req.method,
            "api.projectSlug": ctx.projectSlug ?? "unknown",
        });
    }
    canResolveAsPage(req, pathname) {
        return pathname !== "/api" &&
            !pathname.startsWith("/api/") &&
            (req.method === "GET" || req.method === "HEAD");
    }
    async prepareApiSourceSnapshot(req, ctx, pathname, mustDenyProjectExecution, canResolveAsPage) {
        if (!canResolveAsPage) {
            await ensurePreviewSourceSnapshotFresh(ctx);
            return;
        }
        await preparePreviewDocumentSourceSnapshot(ctx, () => this.handleWithContext(req, ctx, pathname, mustDenyProjectExecution));
    }
    async handleDiscoveredApiRequest(req, ctx, pathname, canResolveAsPage) {
        if (canResolveAsPage && await this.isPageRequest(pathname, ctx, req.signal)) {
            return this.continue();
        }
        const apiRes = await this.executeApiRoute(req, ctx);
        if (!apiRes) {
            this.logDebug("[API-Wrapper] API handler returned null, continuing to next handler", { pathname }, ctx);
            return this.continue();
        }
        this.logDebug("[API-Wrapper] API handler returned response", { pathname, status: apiRes.status }, ctx);
        return this.respond(this.finalizeApiResponse(req, ctx, apiRes));
    }
    async executeApiRoute(req, ctx) {
        // OPTIONS is authenticated by APIRouteHandler before discovery. The
        // callback runs after a matched route's auth decision but before the
        // route module is loaded or executed.
        const isOptionsRequest = req.method.toUpperCase() === "OPTIONS";
        const admitInference = createHostApplicationInferenceAdmission(req, ctx);
        if (!isOptionsRequest) {
            // Lazy per-project primitive discovery (agents, tools) on first
            // access. Must run within runWithContext so VFS and registry scope
            // are correct.
            await ensureProjectDiscovery(ctx);
        }
        const executeRoute = () => withApiHandler(ctx, (api) => api.handle(req, ctx, isOptionsRequest
            ? {
                beforeOptionsDispatch: async () => {
                    await ensureProjectDiscovery(ctx);
                },
            }
            : undefined), { sourceSnapshotReady: true });
        if (admitInference) {
            return await runWithApplicationInferenceAdmission(admitInference, executeRoute, req.signal);
        }
        return await executeRoute();
    }
    async handleDeniedProjectExecution(req, ctx, pathname) {
        if (isPreflightRequest(req)) {
            const response = await handleCORSPreflight({
                request: req,
                config: ctx.securityConfig?.cors,
                allowMethods: DEFAULT_CORS_METHODS.join(", "),
                allowHeaders: getApplicationPreflightHeaders(req, {
                    denyHeaders: ctx.applicationIdentityHeaderNames ?? [],
                }),
            });
            response.headers.set("Allow", DEFAULT_CORS_METHODS.join(", "));
            return this.respond(this.finalizePreflightResponse(req, ctx, response));
        }
        // A shared runtime without an explicit execution grant cannot serve any
        // project-owned route. Reject before refreshing or classifying tenant
        // source that no downstream handler is allowed to execute.
        return this.projectExecutionUnavailable(req, ctx, pathname);
    }
    handlePreparedFrameworkPreflight(req, ctx) {
        if (req.method.toUpperCase() !== "OPTIONS" || !ctx.frameworkPreflightResponse)
            return null;
        return this.respond(this.finalizePreflightResponse(req, ctx, ctx.frameworkPreflightResponse));
    }
    projectExecutionUnavailable(req, ctx, pathname, detail = "Shared runtimes do not execute tenant API modules in the host process or same-process Workers") {
        const problem = createErrorResponseFromDefinition(PROJECT_EXECUTION_UNAVAILABLE, {
            detail,
            instance: pathname,
        });
        const response = this.createResponseBuilder(ctx)
            .withCORS(req, ctx.securityConfig?.cors)
            .withSecurity(ctx.securityConfig ?? undefined, req)
            .withCache("no-store")
            .withHeaders(problem.headers)
            .build(req.method === "HEAD" ? null : problem.body, problem.status);
        return this.respond(response, { executionTopology: "dedicated-runtime-required" });
    }
    finalizePreflightResponse(req, ctx, response) {
        // The prepared response already carries the validated CORS policy headers;
        // only security and response headers are added here.
        return this.createResponseBuilder(ctx)
            .withSecurity(ctx.securityConfig ?? undefined, req)
            .withHeaders(response.headers)
            .build(response.body, response.status);
    }
    finalizeApiResponse(req, ctx, response) {
        return this.createResponseBuilder(ctx)
            .withCORS(req, ctx.securityConfig?.cors)
            .withSecurity(ctx.securityConfig ?? undefined, req)
            .withHeaders(response.headers)
            .build(response.body, response.status);
    }
    async isPageRequest(pathname, ctx, signal) {
        const slug = pathname === "/" ? "" : pathname.replace(/^\/+|(?<!\/)\/+$/g, "");
        const pageResolver = new PageResolver({
            projectDir: ctx.projectDir,
            projectId: ctx.projectId,
            config: ctx.config ?? {},
            adapter: ctx.adapter,
        });
        try {
            return await pageResolver.pageExists(slug, { signal });
        }
        catch (error) {
            if (signal?.aborted)
                throw error;
            this.logDebug("[API-Wrapper] Page ownership is indeterminate; preserving API discovery", {
                pathname,
                error: this.getErrorMessage(error),
            }, ctx);
            return false;
        }
    }
}
